unt end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 join m_loan_charge_paid_by pd on pd.loan_transaction_id = t.id                 join m_loan_charge c on c.id = pd.loan_charge_id                 join m_charge mc on mc.id = c.charge_id                 and mc.is_penalty = true                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 true AS reversal_indicator,                 \'Interest\' AS Allocation_Type,                 case when t.interest_portion_derived is null then 0 else t.interest_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 true AS reversal_indicator,                 \'Principal\' AS Allocation_Type,                 case when t.principal_portion_derived is null then 0 else t.principal_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})               UNION ALL               SELECT                 \'${endDate}\' AS transactiondate,                 t.id,                 l.name AS product,                 t.transaction_type_enum AS transaction_type,                 d.payment_type_id,                 \'\' as chargetype,                 true AS reversal_indicator,                 \'Unallocated Credit (UNC)\' AS Allocation_Type,                 case when t.overpayment_portion_derived is null then 0 else t.overpayment_portion_derived end AS amount               FROM                 m_loan_transaction t                 JOIN m_loan m ON m.id = t.loan_id                 JOIN m_product_loan l ON l.id = m.product_id                 left join m_payment_detail d on d.id = t.payment_detail_id               WHERE                 t.reversed_on_date = \'${endDate}\'                 and t.transaction_type_enum = 26                 and (t.office_id = ${officeId})             ) a           GROUP BY             a.transactiondate,             a.product,             a.transaction_type,             a.payment_type_id,             a.chargetype,             a.reversal_indicator,             a.Allocation_Type           order by             1,             2,             3,             4,             5,             6,             7 ','Transaction Summary Report',0,1,0),(199,'Trial Balance Summary Report with Asset Owner','Table',NULL,'Accounting','select * from (SELECT distinct \'${endDate}\'                                                 AS postingdate,                       loan.pname                                                   AS product,                       loan.gl_code                                                 AS glacct,                       loan.glname                                                  AS description,                       COALESCE((select external_id from m_external_asset_owner where id = loan.assetowner),                                \'self\')                                             as assetowner,                       loan.openingbalance                                          AS beginningbalance,                       (loan.debitamount * 1)                                       AS debitmovement,                       (loan.creditamount * -1)                                     AS creditmovement,                       (loan.openingbalance + loan.debitamount - loan.creditamount) AS endingbalance       FROM (SELECT distinct COALESCE(g.pname, loanproduct.productname)                            pname,                             COALESCE(g.gl_code, loanproduct.glcode)                               gl_code,                             COALESCE(g.glname, loanproduct.glname)                                glname,                             COALESCE(debits.assetowner, loanproduct.assetowner)                   assetowner,                             COALESCE(debits.debitamount, 0) - COALESCE(debits.creditamount, 0) AS openingbalance,                             COALESCE(loanproduct.debitamount, 0)                               AS debitamount,                             COALESCE(loanproduct.creditamount, 0)                              AS creditamount             FROM (SELECT distinct ag.gl_code, ag.id, pl.NAME AS pname, ag.NAME AS glname                   FROM acc_gl_account ag                            JOIN acc_product_mapping am ON am.gl_account_id = ag.id AND am.product_type = 1                            JOIN m_product_loan pl ON pl.id = am.product_id) g                      LEFT JOIN (SELECT lp.NAME                                                                  AS productname,                                        acc_gl_account.gl_code                                                   AS glcode,                                        acc_gl_account.NAME                                                      AS glname,                                        case when aw.owner_id is null then 0 else aw.owner_id end                   assetowner,                                        Sum(CASE WHEN acc_gl_journal_entry.type_enum = 2 THEN amount ELSE 0 END) AS debitamount,                                        Sum(CASE WHEN acc_gl_journal_entry.type_enum = 1 THEN amount ELSE 0 END) AS creditamount                                 FROM acc_gl_account                                          JOIN acc_gl_journal_entry                                               ON acc_gl_account.id = acc_gl_journal_entry.account_id                                          JOIN m_loan m ON m.id = acc_gl_journal_entry.entity_id                                          JOIN m_product_loan lp ON lp.id = m.product_id                                          left join m_external_asset_owner_journal_entry_mapping aw                                                    on aw.journal_entry_id = acc_gl_journal_entry.id                                 WHERE acc_gl_journal_entry.entity_type_enum = 1                                   AND acc_gl_journal_entry.manual_entry = false                                   AND acc_gl_journal_entry.submitted_on_date < \'${endDate}\'                                   AND (acc_gl_journal_entry.office_id = ${officeId})                                 GROUP BY productname, glcode, glname, assetowner                                 ORDER BY glcode) debits ON g.gl_code = debits.glcode AND debits.productname = g.pname                      full outer join (select lp.name                                                                  as productname,                                              account_id,                                              acc_gl_account.gl_code                                                   as glcode,                                              acc_gl_account.name                                                      as glname,                                              case when aw.owner_id is null then 0 else aw.owner_id end                   assetowner,                                              sum(case when acc_gl_journal_entry.type_enum = 2 then amount else 0 end) as debitamount,                                              sum(case when acc_gl_journal_entry.type_enum = 1 then amount else 0 end) as creditamount                                       from acc_gl_journal_entry                                                join acc_gl_account on acc_gl_account.id = acc_gl_journal_entry.account_id                                                join m_loan m on m.id = acc_gl_journal_entry.entity_id                                                join m_product_loan lp on lp.id = m.product_id                                                left join m_external_asset_owner_journal_entry_mapping aw                                                          on aw.journal_entry_id = acc_gl_journal_entry.id                                       where acc_gl_journal_entry.entity_type_enum = 1                                         and acc_gl_journal_entry.manual_entry = false                                         and acc_gl_journal_entry.submitted_on_date = \'${endDate}\'                                         and (acc_gl_journal_entry.office_id = ${officeId})                                       group by productname, account_id, glcode, glname, assetowner                                       order by glcode) loanproduct                                      on g.gl_code = loanproduct.glcode and loanproduct.productname = g.pname and                                         debits.assetowner = loanproduct.assetowner) loan) a where a.endingbalance != 0    or a.debitmovement != 0    or a.creditmovement != 0','Trial Balance Summary Report with Asset Owner',0,1,0),(200,'Transaction Summary Report with Asset Owner','Table',NULL,'Accounting','SELECT \'${endDate}\'                                                            AS TransactionDate,        a.product                                                               AS Product,        case            when a.transaction_type = 9999 then \'Asset Transfer\'            when a.transaction_type = 99999 then \'Asset Buyback\'            else (SELECT enum_message_property                  FROM r_enum_value                  WHERE enum_name = \'transaction_type_enum\'                    and enum_id = a.transaction_type) end                       as TransactionType_Name,        (select value from m_payment_type where id = a.payment_type_id)         as PaymentType_Name,        a.chargetype                                                            as chargetype,        a.reversal_indicator                                                    AS Reversed,        a.Allocation_Type                                                       AS Allocation_Type,        (select code_value from m_code_value where id = a.charge_off_reason_id) AS Chargeoff_ReasonCode,        case            when a.transaction_type = 9999 then sum(a.amount) * + 1            when a.transaction_type = 99999 then sum(a.amount) * - 1            when a.transaction_type IN (2, 23, 21, 22, 24, 4, 5, 8, 6, 27, 9, 26, 28) AND a.reversal_indicator = false                then sum(a.amount) * -1            when a.transaction_type IN (2, 23, 21, 22, 24, 4, 5, 8, 6, 27, 9, 26, 28) AND a.reversal_indicator = true                then sum(a.amount) * + 1            when a.transaction_type IN (1, 10, 25, 20) AND a.reversal_indicator = false then sum(a.amount) * + 1            when a.transaction_type IN (1, 10, 25, 20) AND a.reversal_indicator = true 